43	    }
44	
45	    private void report(String incidentKey) throws Exception {
46	        mvc.perform(post("/api/incidents")
47	                        .contentType(MediaType.APPLICATION_JSON)
48	                        .content("{\"incidentKey\":\"" + incidentKey
49	                                + "\",\"severity\":\"S1\",\"summary\":\"s\",\"reporter\":\"r\"}"))
