61	                .andExpect(jsonPath("$.commander").value(actor));
62	    }
63	
64	    @Test
65	    void apiMainFlow() throws Exception {
66	        report("INC-300");
67	        takeover("INC-300", "alice");
68	
69	        mvc.perform(post("/api/incidents/{k}/actions", "INC-300")
70	                        .header("X-Actor-Id", "alice")
71	                        .contentType(MediaType.APPLICATION_JSON)
72	                        .content("{\"commandKey\":\"" + key()
73	                                + "\",\"actionKey\":\"A1\",\"actionType\":\"NOTE\",\"note\":\"n\","
74	                                + "\"occurredAt\":\"2026-09-21T08:00:00Z\"}"))
75	                .andExpect(status().isOk())
76	                .andExpect(jsonPath("$.actor").value("alice"));
77	
78	        mvc.perform(post("/api/incidents/{k}/transfers", "INC-300")
79	                        .header("X-Actor-Id", "alice")
