package com.example.starter.incident;

/**
 * 升级记录状态：OPEN 待确认 / ACKNOWLEDGED 已确认 / CANCELLED 已取消。
 * OPEN 仅能由当前指挥人确认进入 ACKNOWLEDGED，或在事件进入 CONTAINED 时原子置为 CANCELLED；
 * 已确认记录保留，不允许回退。
 */
public enum EscalationStatus {

    /** 逾期未遏制，等待当前指挥人确认。 */
    OPEN,

    /** 当前指挥人已提交处置说明并确认。 */
    ACKNOWLEDGED,

    /** 事件进入 CONTAINED 时仍为 OPEN，被原子取消；已确认记录不受影响。 */
    CANCELLED
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * “逾期未遏制”升级记录实体，对应 incident_escalations 表；每个事件至多一条。
 * deadline 为首次接管时按严重等级确定的遏制期限（UTC），交接不重置；
 * triggeredAt 为检查命中逾期的触发时刻（UTC），commander 为触发当时的当前指挥人；
 * dispositionNote/acknowledgedBy/acknowledgedAt 仅 ACKNOWLEDGED 有值，其余状态为空。
 */
public record Escalation(
        long id,
        long incidentId,
        EscalationStatus status,
        Instant deadline,
        Instant triggeredAt,
        String commander,
        String dispositionNote,
        String acknowledgedBy,
        Instant acknowledgedAt,
        Instant createdAt) {
}

