        clock.set(T0.plus(1, ChronoUnit.MINUTES));
        String commandKey = key();
        assertApiStatus(() -> service.acknowledgeEscalation(ik, "alice",
                new EscalationAckRequest(commandKey, "说明")), HttpStatus.CONFLICT);
